// Authored overhead rigs (R1-T3, D-057): string lights, paper lanterns, bunting, laundry lines, the bazaar vault. The SVG sources are
// embedded in arena-overhead-data.js (generated by tools/gen-arena-overhead.js). P.ArenaOverhead.draw(R, s, theme, kind, x, y, o)
// draws the hood's rig and returns true; it returns false while the image decodes or when the hood has none, and the caller then draws
// the procedural rig. Two runtime parts the art cannot hold:
//  - glows: the bulbs and lanterns light up with a slow twinkle (about 0.5 per second, so far under the 3 flashes a second limit (design-system 11);
//    steady with Reduce motion);
//  - fade: design-system 6 rule 5, overhangs fade to 30% alpha when the player or a telegraph is under them, eased over ~0.15 s.
// o.v (0..1) picks the variant. View only; the sim never reads this.
P.ArenaOverhead = (function () {
  var A = {}, IMG = {}, RASTER = {}, GLOW = {}, FADE = {}, pending = 0, FLOOR = 0.3, FADE_HOLD = 0.34;   // a fade target may flip at most every 0.34 s (3 a second, design-system 11)

  function load() {
    var data = P.ArenaOverheadData || {};
    Object.keys(data).forEach(function (id) {
      Object.keys(data[id]).forEach(function (kind) {
        data[id][kind].forEach(function (d, v) {
          var im = new Image(), key = id + '|' + kind + '|' + v;
          pending++;
          im.onload = function () { IMG[key] = im; RASTER = {}; pending--; };
          im.onerror = function () { pending--; };
          im.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(d.svg);
        });
      });
    });
  }

  function raster(key, d, k) {
    var rk = key + '|' + k, t = RASTER[rk], cv;
    if (t) return t;
    cv = document.createElement('canvas'); cv.width = Math.ceil(d.w * k); cv.height = Math.ceil(d.h * k);
    cv.getContext('2d').drawImage(IMG[key], 0, 0, cv.width, cv.height);
    return (RASTER[rk] = cv);
  }

  function glowCv(col) {
    var cv = GLOW[col], g, gr;
    if (cv) return cv;
    cv = GLOW[col] = document.createElement('canvas'); cv.width = cv.height = 64;
    g = cv.getContext('2d'); gr = g.createRadialGradient(32, 32, 0, 32, 32, 32);
    gr.addColorStop(0, col); gr.addColorStop(1, 'rgba(0,0,0,0)');
    g.fillStyle = gr; g.fillRect(0, 0, 64, 64);
    return cv;
  }

  // Is the player or a telegraph under the screen rectangle? Returns the target alpha factor (1 or FLOOR).
  function under(R, s, x0, y0, x1, y1) {
    var u = R.ppm, m = 0.15 * u, h = s.hero, hx, hy, hit = false;
    function box(ax0, ay0, ax1, ay1) { return ax1 > x0 - m && ax0 < x1 + m && ay1 > y0 - m && ay0 < y1 + m; }
    if (h) { hx = R.X(h.x); hy = R.Y(h.y); hit = box(hx - 0.55 * u, hy - 1.9 * u, hx + 0.55 * u, hy + 0.15 * u); }
    [(s.dir && s.dir.telegraphs) || [], s.enemyTele || []].forEach(function (list) {
      list.forEach(function (tg) {
        if (hit || tg.r == null || tg.x == null) return;
        hit = box(R.X(tg.x) - tg.r * u, R.Y(tg.y) - tg.r * u, R.X(tg.x) + tg.r * u, R.Y(tg.y) + tg.r * u);
      });
    });
    return hit ? FLOOR : 1;
  }
  function fade(key, target) {
    var now = performance.now() / 1000, st = FADE[key] || (FADE[key] = { a: 1, t: now, tgt: target, flipAt: -1e9 }), dt = Math.min(0.1, Math.max(0, now - st.t));
    if (target !== st.tgt && now - st.flipAt >= FADE_HOLD) { st.tgt = target; st.flipAt = now; }   // a hero jittering on the edge cannot flip the rig faster than 3 a second
    st.t = now; st.a += (st.tgt - st.a) * (1 - Math.exp(-dt / 0.15));
    return st.a;
  }

  A.ready = function () { return pending === 0; };
  A.has = function (theme, kind) { return !!(P.ArenaOverheadData && P.ArenaOverheadData[theme] && P.ArenaOverheadData[theme][kind]); };
  // D-060: a 'hood.sN' entry (N = 1-based stage) is the hood's art on that stage only.
  function stageId(hood, s) {
    var d = P.ArenaOverheadData, k;
    if (!d || !s || !P.Themes) return hood;
    k = hood + '.s' + (P.Themes.subIndex(s) + 1);
    return d[k] ? k : hood;
  }
  // The rig kind for this hood on this stage: a stage entry's kind (it may be a hood whose theme says 'none'), else the theme's kind.
  A.rig = function (hood, s, dflt) {
    var sid = stageId(hood, s);
    return sid !== hood ? Object.keys(P.ArenaOverheadData[sid])[0] : dflt;
  };
  A.draw = function (R, s, hood, kind, x, y, o) {
    var theme = stageId(hood, s), set = P.ArenaOverheadData && P.ArenaOverheadData[theme] && P.ArenaOverheadData[theme][kind], v, key, d, u, X, Y, c, k, x0, y0, a, calm, now, i, g, tw;
    if (!set) return false;
    v = Math.min(set.length - 1, Math.floor(((o && o.v) || 0) * set.length)); key = theme + '|' + kind + '|' + v; d = set[v];
    if (!IMG[key]) return false;
    c = R.ctx; u = R.ppm; X = R.X(x); Y = R.Y(y); x0 = X - d.ax * u; y0 = Y - d.ay * u;
    a = fade(kind + ':' + Math.round(y * 10), under(R, s, x0, y0, x0 + d.w * u, y0 + d.h * u));
    k = Math.max(1, Math.round(u * (R.dpr || 1)));
    c.save(); c.globalAlpha = d.alpha * a;
    c.drawImage(raster(key, d, k), x0, y0, d.w * u, d.h * u);
    if (d.glows.length) {
      calm = !!(P.Settings && ((P.Settings && P.Settings.reduceMotion) || (P.Settings && P.Settings.reduceFlash))); now = performance.now() / 1000;   // steady glows under either setting (D-060 Zindanlar torches)
      c.globalCompositeOperation = 'lighter';
      for (i = 0; i < d.glows.length; i++) {
        g = d.glows[i]; tw = calm ? 1 : 0.75 + 0.25 * Math.sin(now * 3 + i * 1.7 + y);
        c.globalAlpha = 0.5 * tw * a;
        c.drawImage(glowCv(g[3]), X + g[0] * u - g[2] * u, Y + g[1] * u - g[2] * u, g[2] * u * 2, g[2] * u * 2);
      }
    }
    c.restore();
    return true;
  };
  load();
  return A;
})();
